from __future__ import annotations

from fastapi.responses import HTMLResponse

from .main import app


PAGE = r'''<!doctype html><html lang="ar" dir="rtl"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مركز تدخل المدرس</title><style>
:root{--bg:#f5f7fb;--card:#fff;--text:#172033;--muted:#667085;--line:#e4e7ec;--brand:#2447a8;--bad:#b42318;--warn:#b54708;--good:#067647}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:system-ui,-apple-system,sans-serif}main{max-width:1250px;margin:auto;padding:16px}.box{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:16px;margin:12px 0;box-shadow:0 3px 14px #1018280a}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}.card{border:1px solid var(--line);border-radius:13px;padding:12px}.big{font-size:26px;font-weight:800}.muted{color:var(--muted);font-size:13px}.bad{color:var(--bad)}.warn{color:var(--warn)}.good{color:var(--good)}button{padding:9px 11px;border:1px solid var(--line);border-radius:9px;font:inherit;background:white;cursor:pointer}button.primary{background:var(--brand);color:#fff;border-color:var(--brand)}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid var(--line);text-align:right;vertical-align:top}a{color:#175cd3;text-decoration:none}.scroll{overflow:auto}@media(max-width:760px){main{padding:9px}.box{padding:12px;border-radius:14px}table{min-width:1000px}}</style><main>
<div class=box><a href="/admin/dashboard">لوحة التحكم</a> · <a href="/admin/intervention-queue">قائمة المخاطر</a><h1>مركز تدخل المدرس</h1><p class=muted>سجّل التدخل البشري ونتيجته. المنصة تقيس إشارات الخطر فقط ولا ترسل رسالة أو تتخذ قرارًا بدل المدرس.</p><div id=msg class=muted aria-live=polite></div></div><div id=summary class=grid></div><div class="box scroll"><h2>حالات التدخل</h2><table><thead><tr><th>الطالب</th><th>الإجراء</th><th>الحالة</th><th>قبل</th><th>بعد</th><th>الملاحظة</th><th>الإجراء</th></tr></thead><tbody id=cases></tbody></table></div><div class="box scroll"><h2>طلاب يحتاجون قرار المدرس</h2><table><thead><tr><th>الطالب</th><th>الأولوية</th><th>السبب</th><th>الاقتراح</th><th></th></tr></thead><tbody id=queue></tbody></table></div><script>
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const labels={baseline_assessment:'قياس خط أساس',reengage_student:'إعادة إشراك',adaptive_practice:'تدريب علاجي',mistake_review:'مراجعة أخطاء',monitor:'متابعة',custom:'مخصص'};async function api(url,opt){let r=await fetch(url,opt),x=await r.json().catch(()=>null);if(r.status===401){location.href='/admin/login';throw new Error('Authentication required')}if(!r.ok)throw new Error(typeof x?.detail==='string'?x.detail:(x?.detail?.message||'تعذر تنفيذ العملية'));return x}async function openCase(id,type){let note=prompt('ملاحظة المدرس عند فتح الحالة (اختياري):')||null;try{await api('/api/admin/interventions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({student_id:id,intervention_type:type,note})});msg.textContent='تم فتح حالة تدخل.';load()}catch(e){msg.textContent=e.message}}async function finish(id){let outcome=prompt('سجل نتيجة التدخل قبل الإغلاق:');if(outcome===null)return;try{await api('/api/admin/interventions/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'done',outcome_note:outcome})});msg.textContent='تم إغلاق التدخل وقياس الخطر الحالي.';load()}catch(e){msg.textContent=e.message}}async function dismiss(id){if(!confirm('إغلاق الحالة بدون تنفيذ؟'))return;try{await api('/api/admin/interventions/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:'dismissed'})});load()}catch(e){msg.textContent=e.message}}async function load(){try{let [s,c,q]=await Promise.all([api('/api/admin/interventions/summary'),api('/api/admin/interventions?limit=100'),api('/api/admin/intervention-queue?limit=100')]);summary.innerHTML=[['مفتوحة',s.open||0],['مخططة',s.planned||0],['مكتملة',s.done||0],['تحسن بعد التدخل',s.improved||0],['متوسط خفض الخطر',s.average_risk_reduction==null?'—':s.average_risk_reduction]].map(v=>'<div class=card><div class=muted>'+esc(v[0])+'</div><div class=big>'+esc(v[1])+'</div></div>').join('');cases.innerHTML=(c.items||[]).map(v=>'<tr><td><b>'+esc(v.student_name)+'</b></td><td>'+esc(labels[v.intervention_type]||v.intervention_type)+'</td><td>'+esc(v.status)+'</td><td>'+esc(v.pre_risk_score??'—')+'</td><td>'+esc(v.post_risk_score??'—')+'</td><td>'+esc(v.outcome_note||v.note||'—')+'</td><td>'+(v.status==='open'||v.status==='planned'?'<button class=primary onclick="finish('+v.id+')">تم التنفيذ</button> <button onclick="dismiss('+v.id+')">إغلاق</button>':'—')+'</td></tr>').join('')||'<tr><td colspan=7 class=muted>لا توجد حالات تدخل مسجلة.</td></tr>';let active=new Set((c.items||[]).filter(v=>v.status==='open'||v.status==='planned').map(v=>Number(v.student_id)));queue.innerHTML=(q.items||[]).map(v=>'<tr><td><b>'+esc(v.student_name)+'</b></td><td class="'+(v.priority==='high'?'bad':'warn')+'">'+esc(v.priority)+' · '+v.score+'/100</td><td>'+v.reasons.map(esc).join('<br>')+'</td><td>'+esc(labels[v.next_action]||v.next_action)+'</td><td>'+(active.has(Number(v.student_id))?'<span class=good>حالة مفتوحة</span>':'<button onclick="openCase('+v.student_id+',\''+esc(v.next_action)+'\')">فتح تدخل</button>')+'</td></tr>').join('')}catch(e){msg.textContent=e.message}}
load();</script></main></html>'''


@app.get("/admin/interventions", response_class=HTMLResponse)
def intervention_cases_page():
    return PAGE
